import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import {
  Award,
  Calendar,
  Download,
  Eye,
  Rotate3D,
  X,
} from 'lucide-react';

import { certificationsData } from '../data/certifications';
import type { CertificationItem } from '../types/portfolio';

const SUPPLIED_IHUB_CERTIFICATE = "data:image/jpeg;base64,";
const SUPPLIED_LPU_CERTIFICATE = "data:image/jpeg;base64,";

type LocalCertificate = CertificationItem & {
  isSupplied?: boolean;
};

function normalize(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]/g, '');
}

function certificateKey(cert: CertificationItem): string {
  const title = normalize(cert.title);
  const issuer = normalize(cert.issuer);

  if (title.includes('pythonprogramming') && issuer.includes('ihub')) {
    return 'ihub-python-programming';
  }

  if (
    title.includes('objectorientedprogramming') &&
    issuer.includes('lovelyprofessionaluniversity')
  ) {
    return 'lpu-oop-cpp';
  }

  return `${title}::${issuer}`;
}

function buildCertificateList(): LocalCertificate[] {
  const seen = new Set<string>();
  const output: LocalCertificate[] = [];

  // Start from the portfolio's existing certification data.
  // This prevents duplicate cards when the supplied credentials already exist.
  for (const cert of certificationsData) {
    const key = certificateKey(cert);
    if (seen.has(key)) continue;
    seen.add(key);

    if (key === 'ihub-python-programming') {
      output.push({
        ...cert,
        certificateImage: SUPPLIED_IHUB_CERTIFICATE,
      });
      continue;
    }

    if (key === 'lpu-oop-cpp') {
      output.push({
        ...cert,
        certificateImage: SUPPLIED_LPU_CERTIFICATE,
      });
      continue;
    }

    output.push({ ...cert });
  }

  // Add the supplied credentials only when they are not already represented
  // in the original data.
  if (!seen.has('ihub-python-programming')) {
    output.push({
      id: 'cert-ihub-python-programming-supplied',
      title: 'Certificate of Completion — Python Programming',
      issuer: 'iHUB DivyaSampark, Indian Institute of Technology Roorkee',
      date: '18-09-2024',
      credentialId: 'iHUB DivyaSampark',
      certificateImage: SUPPLIED_IHUB_CERTIFICATE,
      summary:
        'Certificate of Completion for Python Programming conducted by iHUB DivyaSampark, IIT Roorkee.',
      howEarned: 'Completed the supplied Python Programming certificate course.',
      whatIlearned: ['Python Programming'],
      topics: ['Python', 'iHUB DivyaSampark', 'IIT Roorkee'],
      isSupplied: true,
    });
  }

  if (!seen.has('lpu-oop-cpp')) {
    output.push({
      id: 'cert-lpu-merit-oop-cpp-supplied',
      title: 'Certificate of Merit — Object Oriented Programming using C++',
      issuer:
        'Centre for Professional Enhancement, Lovely Professional University',
      date: '13-08-2026',
      credentialId: '491536',
      certificateImage: SUPPLIED_LPU_CERTIFICATE,
      summary:
        'Certificate of Merit for completion of the Object Oriented Programming using C++ skill development course.',
      howEarned:
        'The supplied certificate records the course period as 12-06-2026 to 26-07-2026 and the issue date as 13-08-2026.',
      whatIlearned: ['Object Oriented Programming using C++'],
      topics: ['C++', 'Object Oriented Programming'],
      isSupplied: true,
    });
  }

  return output;
}

function downloadTarget(cert: CertificationItem): string | undefined {
  return cert.certificateFile ?? cert.certificateImage;
}

function downloadName(cert: CertificationItem, href: string): string {
  const ext = href.startsWith('data:image/')
    ? 'jpg'
    : href.split('.').pop() || 'pdf';
  const slug = normalize(cert.title).replace(/\s+/g, '-');
  return `udhaya-nilavan-${slug}.${ext}`;
}

function CertificateModal({
  cert,
  onClose,
}: {
  cert: LocalCertificate | null;
  onClose: () => void;
}) {
  useEffect(() => {
    if (!cert) return;

    const handleKeyDown = (event: globalThis.KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [cert, onClose]);

  if (!cert) return null;

  return (
    <div className="cert-final-modal" role="dialog" aria-modal="true" aria-labelledby="cert-final-modal-title">
      <button
        type="button"
        className="cert-final-modal__backdrop"
        aria-label="Close certificate"
        onClick={onClose}
      />

      <div className="cert-final-modal__panel">
        <button
          type="button"
          className="cert-final-modal__close"
          aria-label="Close certificate dialog"
          onClick={onClose}
        >
          <X size={18} />
        </button>

        <div className="cert-final-modal__image-wrap">
          <img src={cert.certificateImage} alt={cert.title} />
        </div>

        <div className="cert-final-modal__info">
          <span>CERTIFICATE EVIDENCE</span>
          <h3 id="cert-final-modal-title">{cert.title}</h3>
          <p>{cert.summary}</p>

          <div className="cert-final-modal__meta">
            <div>
              <Award size={15} />
              <span>{cert.issuer}</span>
            </div>
            <div>
              <Calendar size={15} />
              <span>{cert.date}</span>
            </div>
            {cert.credentialId ? (
              <div>
                <span className="cert-final-modal__credential-label">ID</span>
                <span>{cert.credentialId}</span>
              </div>
            ) : null}
          </div>

          {downloadTarget(cert) ? (
            <a
              className="cert-final-btn cert-final-btn--primary"
              href={downloadTarget(cert)}
              download={downloadName(cert, downloadTarget(cert)!)}
            >
              <Download size={15} />
              Download certificate
            </a>
          ) : null}
        </div>
      </div>
    </div>
  );
}

function CertificateCard({
  cert,
  index,
  onView,
}: {
  cert: LocalCertificate;
  index: number;
  onView: (cert: LocalCertificate) => void;
}) {
  const [flipped, setFlipped] = useState(false);
  const download = downloadTarget(cert);

  return (
    <article
      className="cert-final-item"
      style={{ '--cert-delay': `${Math.min(index, 8) * 75}ms` } as React.CSSProperties}
    >
      <div className={`cert-final-card ${flipped ? 'is-flipped' : ''}`}>
        <div className="cert-final-card__inner">
          <div className="cert-final-face cert-final-face--front">
            <div className="cert-final-image-wrap">
              <img
                className="cert-final-image"
                src={cert.certificateImage}
                alt={`Certificate: ${cert.title}, issued by ${cert.issuer}`}
                loading={index < 4 ? 'eager' : 'lazy'}
                decoding="async"
              />

              <div className="cert-final-image-actions">
                <button
                  type="button"
                  className="cert-final-view"
                  onClick={() => onView(cert)}
                >
                  <Eye size={14} />
                  VIEW
                </button>
              </div>
            </div>

            <div className="cert-final-body">
              <div className="cert-final-kicker">
                {cert.isSupplied ? 'SUPPLIED CREDENTIAL' : 'VERIFIED CREDENTIAL'}
              </div>

              <h3>{cert.title}</h3>

              <div className="cert-final-meta">
                <span>
                  <Award size={14} />
                  {cert.issuer}
                </span>
                <span>
                  <Calendar size={14} />
                  {cert.date}
                </span>
              </div>

              <div className="cert-final-actions">
                <button
                  type="button"
                  className="cert-final-btn cert-final-btn--primary"
                  onClick={() => onView(cert)}
                >
                  <Eye size={15} />
                  View certificate
                </button>

                <button
                  type="button"
                  className="cert-final-btn cert-final-btn--secondary"
                  onClick={() => setFlipped(true)}
                  aria-label={`Flip ${cert.title} to show details`}
                >
                  <Rotate3D size={15} />
                  Flip
                </button>

                {download ? (
                  <a
                    className="cert-final-btn cert-final-btn--secondary cert-final-download"
                    href={download}
                    download={downloadName(cert, download)}
                  >
                    <Download size={15} />
                    Download
                  </a>
                ) : null}
              </div>
            </div>
          </div>

          <div className="cert-final-face cert-final-face--back">
            <div className="cert-final-back-head">
              <div>
                <span>CREDENTIAL DETAILS</span>
                <small>FLIPPED VIEW</small>
              </div>

              {cert.badgeImage ? (
                <img
                  className="cert-final-badge"
                  src={cert.badgeImage}
                  alt=""
                  aria-hidden="true"
                />
              ) : (
                <div className="cert-final-badge-placeholder">
                  <Award size={24} />
                </div>
              )}
            </div>

            <div className="cert-final-back-content">
              <h3>{cert.title}</h3>

              <div className="cert-final-detail">
                <span>ISSUER</span>
                <p>{cert.issuer}</p>
              </div>

              <div className="cert-final-detail">
                <span>ISSUED</span>
                <p>{cert.date}</p>
              </div>

              {cert.credentialId ? (
                <div className="cert-final-detail">
                  <span>CREDENTIAL ID</span>
                  <p>{cert.credentialId}</p>
                </div>
              ) : null}

              {cert.howEarned ? (
                <div className="cert-final-detail">
                  <span>HOW EARNED</span>
                  <p>{cert.howEarned}</p>
                </div>
              ) : null}

              {cert.whatIlearned?.length ? (
                <div className="cert-final-detail">
                  <span>LEARNING</span>
                  <p>{cert.whatIlearned.join(' • ')}</p>
                </div>
              ) : null}
            </div>

            <div className="cert-final-actions cert-final-actions--back">
              <button
                type="button"
                className="cert-final-btn cert-final-btn--primary"
                onClick={() => onView(cert)}
              >
                <Eye size={15} />
                View certificate
              </button>

              <button
                type="button"
                className="cert-final-btn cert-final-btn--secondary"
                onClick={() => setFlipped(false)}
                aria-label={`Flip ${cert.title} back to certificate`}
              >
                <Rotate3D size={15} />
                Back
              </button>
            </div>
          </div>
        </div>
      </div>
    </article>
  );
}

export function Certifications() {
  const certificates = useMemo(() => buildCertificateList(), []);
  const [viewing, setViewing] = useState<LocalCertificate | null>(null);

  const closeViewing = useCallback(() => {
    setViewing(null);
  }, []);

  return (
    <>
      <style>{CERTIFICATION_STYLES}</style>

      <section
        id="certifications"
        className="cert-final-section"
        aria-labelledby="cert-final-title"
      >
        <div className="cert-final-shell">
          <header className="cert-final-header">
            <div>
              <span className="cert-final-eyebrow">CREDENTIALS / VERIFIED</span>
              <h2 id="cert-final-title">CERTIFICATIONS</h2>
            </div>

            <p>
              Verified certificates and professional credentials. Flip a card for
              its details or open the certificate evidence directly.
            </p>
          </header>

          <div className="cert-final-grid">
            {certificates.map((cert, index) => (
              <CertificateCard
                key={certificateKey(cert)}
                cert={cert}
                index={index}
                onView={setViewing}
              />
            ))}
          </div>

          <div className="cert-final-hint">
            <Rotate3D size={14} />
            <span>FLIP A CARD TO EXPLORE CREDENTIAL DETAILS</span>
          </div>
        </div>
      </section>

      <CertificateModal cert={viewing} onClose={closeViewing} />
    </>
  );
}

